// @pit: {"label": "Patch pit resolveToolInput to decode JSON string literals, add tests, run them"}
async ({ workspace: { read, edit }, shell: { exec } }) => {
  const src = "/tmp/pit/src/tool/input.ts";
  const f = (await read(src, { format: "raw" })).content;
  const next = f.replace(
    `export function resolveToolInput(source: string, params: unknown): unknown {\n  if (typeof params !== "string" || programInputAdmitsString(source) !== false) return params;\n  const text = params.trim();`,
    `export function resolveToolInput(source: string, params: unknown): unknown {\n  if (typeof params !== "string") return params;\n  const text = params.trim();\n  // A string sent JSON-encoded, quotes and \\n escapes included, is never meant literally.\n  if (text.length >= 2 && text.startsWith('"') && text.endsWith('"')) {\n    try {\n      const decoded = JSON.parse(text) as unknown;\n      if (typeof decoded === "string") return decoded;\n    } catch {\n      // Not a JSON string: keep it.\n    }\n  }\n  if (programInputAdmitsString(source) !== false) return params;`,
  ).replace(" * the value through unchanged so validation reports any mismatch against the declared type.\n */",
    " * the value through unchanged so validation reports any mismatch against the declared type. A\n * string that is itself a JSON string literal (\"line\\\\nline\") is decoded for every input.\n */");
  if (next === f) return "no change";
  await edit(src, { revision: null, changes: [{ kind: "replaceFile", content: next }] });
  const tp = "/tmp/pit/test/tool/input.test.ts";
  const t = (await read(tp, { format: "raw" })).content;
  const t2 = t.replace(`    {\n      name: "an already decoded object",`,
`    {
      name: "a JSON-encoded string for a string input",
      source: "async ({}, body: string) => body",
      params: JSON.stringify("Title\\n\\n## Section"),
      expected: "Title\\n\\n## Section",
    },
    {
      name: "a quoted string that is not JSON",
      source: "async ({}, body: string) => body",
      params: '"a\\\\q"',
      expected: '"a\\\\q"',
    },
    {
      name: "an already decoded object",`);
  await edit(tp, { revision: null, changes: [{ kind: "replaceFile", content: t2 }] });
  const r = await exec(`cd /tmp/pit && (test -d node_modules || npm ci --silent >/dev/null 2>&1) && npx vitest run test/tool/input.test.ts 2>&1 | tail -15 && git diff --stat`, { timeoutMs: 250000 });
  return r.stdout + r.stderr;
}
